<script>
// ── FHIR extension & profile URL constants ────────────────────────────────
const CHANGE_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/position-change-reason-profile";

const EXT = {
  POSITION: "http://ihris.org/fhir/StructureDefinition/position-reference",
  EMP_CAT: "http://ihris.org/fhir/StructureDefinition/employment-category",
  DEPARTMENT: "http://ihris.org/fhir/StructureDefinition/department",
  FACILITY: "http://ihris.org/fhir/StructureDefinition/facility",
  DESIGNATION: "http://ihris.org/fhir/StructureDefinition/designation",
  // Position change reason extensions
  CHANGE_REASON: "http://ihris.org/fhir/StructureDefinition/change-reason",
  PREV_POSITION: "http://ihris.org/fhir/StructureDefinition/previous-position",
  CHANGE_DATE: "http://ihris.org/fhir/StructureDefinition/change-date",
  POS_NAME: "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
};

export default {
  name: "PositionView",

  props: {
    queries: {
      type: Object,
      required: true,
      // queries.practitioner → Practitioner FHIR id (without "Practitioner/" prefix)
      // queries.role         → PractitionerRole FHIR id (without "PractitionerRole/" prefix)
    },
  },

  data() {
    return {
      loading: false,
      error: null,

      // Parsed PractitionerRole + enriched position data
      role: {
        active: true,
        designation: "",
        department: "",
        facility: "",
        council: "",
        district: "",
        employmentCategory: "",
        startDate: null,
        endDate: null,
      },

      practitionerName: "",

      // Position change reason records
      positionChanges: [],

      changeHeaders: [
        {
          text: "Previous Position",
          value: "previousPosition",
          sortable: false,
        },
        { text: "Change Reason", value: "reason", sortable: false },
        { text: "Date", value: "date", sortable: false, width: 130 },
      ],
    };
  },

  computed: {
    initials() {
      return this.getInitials(this.practitionerName);
    },
  },

  async mounted() {
    await this.loadAll();
  },

  methods: {
    // ── Orchestration ──────────────────────────────────────────────────
    async loadAll() {
      this.loading = true;
      this.error = null;
      try {
        await Promise.all([this.loadRole(), this.loadPractitioner()]);
        await this.loadBasicRecords();
      } catch (err) {
        console.error("PositionView loadAll error", err);
        this.error = "Failed to load position details. Please try again.";
      } finally {
        this.loading = false;
      }
    },

    // ── PractitionerRole ───────────────────────────────────────────────
    async loadRole() {
      const res = await fetch(`/fhir/PractitionerRole/${this.queries.role}`);
      const data = await res.json();

      this.role.active = data.active !== false;
      this.role.startDate = data.period?.start || null;
      this.role.endDate = data.period?.end || null;

      // Employment category
      const empCat = this.getExt(data, EXT.EMP_CAT, "valueCoding");
      this.role.employmentCategory = empCat?.display || empCat?.code || "";

      // Position Basic → designation + department
      const posRef = this.getExt(data, EXT.POSITION, "valueReference");
      if (posRef?.reference) {
        try {
          const posId = posRef.reference.split("/")[1];
          const posRes = await fetch(`/fhir/Basic/${posId}`);
          const posData = await posRes.json();
          const facilityRef = posData.extension.find(
            (ext) =>
              ext.url === "http://ihris.org/fhir/StructureDefinition/facility",
          )?.valueReference?.reference;
          if (facilityRef) {
            await this.loadFacilityHierarchy(facilityRef);
          }
          await this.enrichPosition(posData);
        } catch (_) {
          this.role.designation = posRef.display || posRef.reference;
        }
      }
    },

    // ── Facility → Council → District hierarchy ────────────────────────
    async loadFacilityHierarchy(facilityRef) {
      try {
        const facRes = await fetch(`/fhir/${facilityRef}`);
        const facData = await facRes.json();
        this.role.facility = facData.name || facilityRef;

        // partOf → council
        const councilRef = facData.partOf?.reference;
        if (councilRef) {
          try {
            const councilRes = await fetch(`/fhir/${councilRef}`);
            const councilData = await councilRes.json();
            this.role.council = councilData.name || councilRef;

            // partOf → district
            const districtRef = councilData.partOf?.reference;
            if (districtRef) {
              try {
                const districtRes = await fetch(`/fhir/${districtRef}`);
                const districtData = await districtRes.json();
                this.role.district = districtData.name || districtRef;
              } catch (err) {
                console.log(err);
              }
            }
          } catch (err) {
            console.log(err);
          }
        }
      } catch (err) {
        console.log(err);
        this.role.facility = facilityRef;
      }
    },

    async enrichPosition(posData) {
      // Designation — follows a valueReference to another Basic
      const desigRef = this.getExt(posData, EXT.DESIGNATION, "valueReference");
      if (desigRef?.reference) {
        try {
          const desigId = desigRef.reference.split("/")[1];
          const desigRes = await fetch(`/fhir/Basic/${desigId}`);
          const desigData = await desigRes.json();
          this.role.designation =
            this.getExt(desigData, EXT.POS_NAME, "valueString") ||
            desigRef.display ||
            "";
        } catch (_) {
          this.role.designation = desigRef.display || "";
        }
      }

      // Department
      const deptCoding = this.getExt(posData, EXT.DEPARTMENT, "valueCoding");
      this.role.department = deptCoding?.display || deptCoding?.code || "";
    },

    // ── Practitioner name ──────────────────────────────────────────────
    async loadPractitioner() {
      try {
        const res = await fetch(
          `/fhir/Practitioner/${this.queries.practitioner}`,
        );
        const data = await res.json();
        this.practitionerName = this.parsePractitionerName(data);
      } catch (_) {
        this.practitionerName = `Practitioner/${this.queries.practitioner}`;
      }
    },

    parsePractitionerName(resource) {
      if (!resource?.name?.length) return "";
      const nameObj = resource.name[0];
      const given = nameObj.given ? nameObj.given.join(" ") : "";
      const family = nameObj.family || "";
      return (given + " " + family).trim();
    },

    // ── Basic records: position change reasons ───────────────────────────
    async loadBasicRecords() {
      try {
        const res = await fetch(
          `/fhir/Basic?practitionerrole=PractitionerRole/${this.queries.role}&_count=100&_sort=-_lastUpdated`,
        );
        const data = await res.json();
        const entries = (data.entry || []).map((e) => e.resource);

        const changeResources = entries.filter((r) =>
          r.meta?.profile?.some((p) => p === CHANGE_PROFILE),
        );

        this.positionChanges = await Promise.all(
          changeResources.map((r) => this.parseChangeReason(r)),
        );
      } catch (err) {
        console.error("loadBasicRecords error", err);
      }
    },

    async parseChangeReason(resource) {
      const entry = {
        id: resource.id,
        previousPosition: "",
        reason: "",
        date:
          this.getExt(resource, EXT.CHANGE_DATE, "valueDate") ||
          this.getExt(resource, EXT.CHANGE_DATE, "valueDateTime") ||
          null,
      };

      const reasonCoding = this.getExt(
        resource,
        EXT.CHANGE_REASON,
        "valueCoding",
      );
      entry.reason = reasonCoding?.display || reasonCoding?.code || "";

      const prevPosRef = this.getExt(
        resource,
        EXT.PREV_POSITION,
        "valueReference",
      );
      if (prevPosRef?.display) {
        entry.previousPosition = prevPosRef.display;
      } else if (prevPosRef?.reference) {
        try {
          const posId = prevPosRef.reference.split("/")[1];
          const posRes = await fetch(`/fhir/Basic/${posId}`);
          const posData = await posRes.json();
          const desigRef = this.getExt(
            posData,
            EXT.DESIGNATION,
            "valueReference",
          );
          if (desigRef?.reference) {
            const desigId = desigRef.reference.split("/")[1];
            const desigRes = await fetch(`/fhir/Basic/${desigId}`);
            const desigData = await desigRes.json();
            entry.previousPosition =
              this.getExt(desigData, EXT.POS_NAME, "valueString") ||
              desigRef.display ||
              prevPosRef.reference;
          } else {
            entry.previousPosition =
              this.getExt(posData, EXT.POS_NAME, "valueString") ||
              prevPosRef.reference;
          }
        } catch (_) {
          entry.previousPosition = prevPosRef.reference;
        }
      }

      return entry;
    },

    // ── Helpers ────────────────────────────────────────────────────────
    getExt(resource, url, type) {
      const ext = resource?.extension?.find((e) => e.url === url);
      return ext ? ext[type] : null;
    },

    getInitials(name = "") {
      return name
        ?.split(" ")
        ?.filter(Boolean)
        ?.slice(0, 2)
        ?.map((w) => w[0].toUpperCase())
        ?.join("");
    },
  },
};
</script>

